{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "In healthy subjects, the absolute bioavailability of aprepitant 80-mg capsules was 0.67 (95% CI 0.62–0.73) versus IV; aprepitant shares the same 3,5-bis(trifluoromethyl)phenyl ethoxy side chain and NK1-antagonist class with the query, supporting F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Fluoxetine, a lipophilic trifluoromethyl-substituted amine, has an absolute oral bioavailability of about 95% in humans, indicating that lipophilic oral drugs of this general type can be highly bioavailable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Flibanserin, a moderately lipophilic CNS-active drug, has an absolute oral bioavailability of 46% in healthy volunteers, still clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Almorexant, a large lipophilic CNS drug, has an absolute oral bioavailability of only 11.2%, showing that lipophilicity alone does not guarantee high F; however, its structural similarity to the query is lower than that of aprepitant.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C41"],
      "claim": "Phenoperidine has a systemic bioavailability of 9.9% after oral administration, another example of low F in a lipophilic basic drug, but it is structurally distant from the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is structurally closest to aprepitant, a human NK1 antagonist with absolute oral bioavailability of 60–67%, well above the 20% threshold. Although some lipophilic CNS drugs such as almorexant and phenoperidine have low F, they are less structurally similar to the query. The preponderance of transferable experimental evidence supports high oral bioavailability.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the query molecule.",
    "The closest analogue, aprepitant, has only moderate Morgan similarity (0.2747) to the query.",
    "No human pharmacokinetic data are available for the exact spiro-lactam piperidine core.",
    "Potential first-pass metabolism and solubility limitations of the query are not directly assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

